(function(){
const $=id=>document.getElementById(id),zones={inside:['ANZ452'],absecon:['ANZ452','ANZ453'],barnegat:['ANZ451','ANZ452','ANZ453']},base={inside:'Stay inside',absecon:'Ocean via Absecon ↔ Cape May',barnegat:'Ocean via Barnegat ↔ Cape May'},cache=new Map();let request=0;
const civil=t=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t));
function shift(date,days){const x=new Date(date+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+days);return x.toISOString().slice(0,10);}
function periodFor(d,date,time){const updated=civil(d.properties.updated),hour=Number((time||'12:00').slice(0,2)),night=hour>=18||hour<6,target=hour<6?shift(date,-1):date,weekday=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return d.properties.periods.find(p=>{const name=p.name.toLowerCase(),isNight=/night|tonight|overnight/.test(name);let day;if(/today|tonight|this afternoon|this evening|overnight/.test(name))day=updated;else if(/tomorrow/.test(name))day=shift(updated,1);else{let ix=weekday.findIndex(w=>name.startsWith(w.toLowerCase()));if(ix<0)return false;let days=(ix-new Date(updated+'T12:00Z').getUTCDay()+7)%7;day=shift(updated,days);}return day===target&&isNight===night;});}
function sea(text){return text.match(/\bseas?\s+[^.]*?\b(?:ft|feet)\b/i)?.[0]||null;}
async function zone(id){const c=cache.get(id);if(c&&Date.now()-c.time<30*60000)return c.data;const res=await fetch('https://api.weather.gov/zones/marine/'+id+'/forecast');if(!res.ok)throw Error('NWS unavailable');const data=await res.json();if(!data.properties?.updated||!Array.isArray(data.properties.periods))throw Error('NWS data unavailable');cache.set(id,{time:Date.now(),data});return data;}
async function update(){const n=++request,date=$('date').value,time=$('time').value,mode=$('routeMode').value;if(!date||!time)return;const box=$('marineForecast');window.njTripWeatherSummary='';box.textContent='Loading National Weather Service forecast…';const fetched=await Promise.allSettled(['ANZ451','ANZ452','ANZ453'].map(zone));if(n!==request)return;const all=Object.fromEntries(['ANZ451','ANZ452','ANZ453'].map((z,i)=>[z,fetched[i].status==='fulfilled'?fetched[i].value:null]));for(const opt of $('routeMode').options){const mode=opt.value,parts=zones[mode].map(z=>all[z]&&periodFor(all[z],date,time)).filter(Boolean),seas=[...new Set(parts.map(p=>sea(p.detailedForecast)).filter(Boolean))];opt.textContent=base[mode]+(mode!=='inside'&&seas.length?' ('+seas.join('; ')+')':'');}
const selected=zones[mode].map(z=>({z,d:all[z],p:all[z]&&periodFor(all[z],date,time)}));
try{const mid=typeof trip!=="undefined"&&trip?NJTide.position(route,(trip.start.distance+trip.finish.distance)/2):{lat:39.36,lon:-74.43},params=new URLSearchParams({latitude:mid.lat.toFixed(2),longitude:mid.lon.toFixed(2),hourly:'temperature_2m,weather_code,precipitation_probability,wind_speed_10m,wind_gusts_10m,wind_direction_10m',temperature_unit:'fahrenheit',wind_speed_unit:'kn',timezone:'America/New_York',forecast_days:'7'}),response=await fetch('https://api.open-meteo.com/v1/forecast?'+params);if(!response.ok)throw Error();const forecast=await response.json();if(n!==request)return;const h=forecast.hourly,indices=h.time.map((v,i)=>v.startsWith(date)?i:-1).filter(i=>i>=0),hour=Number(time.slice(0,2)),index=indices.find(i=>Number(h.time[i].slice(11,13))===hour);if(index===undefined){box.textContent='Weather forecast unavailable for the selected date and time.';window.dispatchEvent(new Event('nj-weather-updated'));return;}const localHour=t=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(t).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day+'T'+p.hour+':00';};let passageTimes=[];if(typeof trip!=='undefined'&&trip){for(let t=trip.departure;t<=trip.end;t+=3600000)passageTimes.push(localHour(t));passageTimes.push(localHour(trip.end));}else passageTimes=[localHour(new Date(date+'T'+time).getTime())];const passageIndices=[...new Set(passageTimes)].map(t=>h.time.indexOf(t)).filter(i=>i>=0);const rng=(key,unit)=>{let vals=passageIndices.map(i=>h[key]?.[i]).filter(Number.isFinite);if(!vals.length)return 'unavailable';const lo=Math.round(Math.min(...vals)),hi=Math.round(Math.max(...vals));return (lo===hi?String(lo):lo+'–'+hi)+unit;};window.njTripWeatherSummary=passageIndices.length?'Expected during passage (route midpoint): temperature '+rng('temperature_2m','°F')+' · wind '+rng('wind_speed_10m',' kt')+' · gusts '+rng('wind_gusts_10m',' kt')+' · precipitation chance '+rng('precipitation_probability','%')+'.'+(passageIndices.length<new Set(passageTimes).size?' Forecast coverage is incomplete.':''):'Trip weather range unavailable.';const code=h.weather_code[index],sky=code===0?'Clear':code===1?'Mostly clear':code===2?'Partly cloudy':code===3?'Overcast':code<=48?'Fog':code<=67?'Rain or drizzle':code<=77?'Snow':code<=82?'Rain showers':code>=95?'Thunderstorms':'Mixed conditions',probs=indices.map(i=>h.precipitation_probability[i]).filter(Number.isFinite),rain=probs.length?Math.max(...probs)+'% max precipitation chance':'Precipitation chance unavailable',marineTexts=zones[mode].flatMap(z=>all[z]?[periodFor(all[z],date,'12:00'),periodFor(all[z],date,'21:00')].filter(Boolean).map(p=>p.detailedForecast):[]),storm=indices.some(i=>h.weather_code[i]>=95)||marineTexts.some(t=>/thunderstorms?/i.test(t)),complete=indices.length===24,stormText=storm?'Thunderstorms mentioned in forecast':complete?'No thunderstorms indicated':'Thunderstorm outlook incomplete';const deg=h.wind_direction_10m[index],dirs=['N','NE','E','SE','S','SW','W','NW'],direction=Number.isFinite(deg)?dirs[Math.round(deg/45)%8]:'';box.textContent=sky+' · '+Math.round(h.temperature_2m[index])+'°F · '+direction+' wind '+Math.round(h.wind_speed_10m[index])+' kt, gusts '+Math.round(h.wind_gusts_10m[index])+' kt · '+rain+' · '+stormText+' · Open-Meteo, route midpoint. Check full forecasts.';window.dispatchEvent(new Event('nj-weather-updated'));}catch(e){if(n===request){box.textContent='General weather forecast unavailable. Check the full forecast.';window.dispatchEvent(new Event('nj-weather-updated'));}}}

for(const id of ['date','time','routeMode'])$(id).addEventListener('change',update);window.addEventListener('load',update);window.addEventListener('nj-trip-updated',update);setInterval(update,30*60000);
})();
